class Solution:
    def numSquares(self, n: int) -> int:
        f = [0] * (n + 1)
        for i in range(1, n + 1):
            minn = float('inf')
            j = 1
            while j * j <= i:
                minn = min(minn, f[i - j * j])
                j += 1
            f[i] = minn + 1
        return f[n]

class Solution:
    def numSquares(self, n: int) -> int:
        if n <= 0:
            return 0
        marked = [False] * (n + 1)
        marked[n] = True
        queue = [n]
        level = 0
        while queue:
            level += 1
            size = len(queue)
            for _ in range(size):
                num = queue.pop(0)
                j = 1
                while j * j <= num:
                    nxt = num - j * j
                    if nxt == 0:
                        return level
                    if not marked[nxt]:
                        queue.append(nxt)
                        marked[nxt] = True
                    j += 1
        return -1
